// Real lake depth: MassWildlife Inland Water Bathymetry contours for Ashland Reservoir (MassGIS, public),
// interpolated onto a 2.5 m game-metre grid.  Byte = depth in quarter-feet (0 = no data / shore).
export const BATHY = { x0:-347, z0:-499, nx:205, nz:373, cell:2.5, b64:"" };
let _g=null;
function build(){const bin=atob(BATHY.b64),g=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)g[i]=bin.charCodeAt(i);return g}
// depth in feet at game (x,z), bilinear; 0 where there is no survey data
export function depthFtAt(x,z){
  if(!_g)_g=build();
  const fx=(x-BATHY.x0)/BATHY.cell-.5, fy=(z-BATHY.z0)/BATHY.cell-.5;
  if(fx<0||fy<0||fx>=BATHY.nx-1||fy>=BATHY.nz-1)return 0;
  const x0=fx|0,y0=fy|0,tx=fx-x0,ty=fy-y0,W=BATHY.nx;
  const a=_g[y0*W+x0],b=_g[y0*W+x0+1],c=_g[(y0+1)*W+x0],d=_g[(y0+1)*W+x0+1];
  return ((a*(1-tx)+b*tx)*(1-ty)+(c*(1-tx)+d*tx)*ty)/4;
}
